#!/usr/bin/env Rscript
args<-grep('^--file=',commandArgs(FALSE),value=TRUE)[1];here<-dirname(normalizePath(sub('^--file=','',args)))
suppressPackageStartupMessages({library(ggplot2);library(cowplot);library(svglite)})
cowplot::set_null_device('agg')
z<-read.csv(file.path(here,'summary.csv'));navy<-'#315778';gold<-'#93640B';ink<-'#202B37'
th<-function() theme_classic(base_size=10,base_family='Arial')+theme(text=element_text(colour=ink),axis.text=element_text(size=9,colour=ink),axis.line=element_line(linewidth=.28),axis.ticks=element_line(linewidth=.28),legend.title=element_blank(),legend.position='bottom',legend.text=element_text(size=8),legend.key.width=grid::unit(6,'mm'),plot.margin=margin(17,8,8,17))
xs<-scale_x_log10(breaks=c(100,300,1000,3000),labels=c('100','300','1,000','3,000'))
means<-function(r){d<-subset(z,rho==r & contrast=='triple' & arm!='markov');d$arm<-factor(d$arm,levels=c('directed','control'),labels=c('Asymmetric model','Reversible control'));truth<-unique(d$truth[d$arm=='Asymmetric model']);ggplot(d,aes(n,mean,colour=arm,shape=arm))+geom_hline(yintercept=0,colour=ink,linewidth=.25)+geom_hline(yintercept=truth,colour=navy,linetype='dotted',linewidth=.4)+geom_errorbar(aes(ymin=q025,ymax=q975),width=.08,position=position_dodge(.1),linewidth=.45)+geom_point(position=position_dodge(.1),size=2)+scale_colour_manual(values=c('Asymmetric model'=navy,'Reversible control'=gold))+scale_shape_manual(values=c(16,1))+xs+labs(x='Trajectory length (symbols)',y='Triple contrast')+th()}
rates<-function(r){d<-subset(z,rho==r);d$contrast<-factor(d$contrast,levels=c('triple','lag2'),labels=c('Triple','Lag 2'));d$arm<-factor(d$arm,levels=c('directed','control','markov'),labels=c('Asymmetric','Reversible phase','Reversible Markov'));ggplot(d,aes(n,exceed,colour=contrast,linetype=arm,shape=arm,group=interaction(contrast,arm)))+geom_hline(yintercept=.05,colour=ink,linewidth=.3,linetype='dotted')+geom_line(linewidth=.6)+geom_point(size=1.5)+geom_errorbar(aes(ymin=exceed_lo,ymax=exceed_hi),width=.04,linewidth=.35)+scale_colour_manual(values=c('Triple'=navy,'Lag 2'=gold))+scale_linetype_manual(values=c('solid','dashed','dotted'))+scale_shape_manual(values=c(16,1,3))+xs+scale_y_continuous(limits=c(0,1.03),breaks=c(0,.25,.5,.75,1))+labs(x='Trajectory length (symbols)',y='Fraction above threshold')+th()+theme(legend.position='none')+annotate('text',x=120,y=.94,label='Triple',hjust=0,colour=navy,family='Arial',size=2.7)+annotate('text',x=120,y=.84,label='Lag 2',hjust=0,colour=gold,family='Arial',size=2.7)}
a<-means(.2);b<-means(.65);c<-rates(.2);d<-rates(.65)
g<-ggdraw(plot_grid(a,b,c,d,ncol=2));for(k in 1:4)g<-g+draw_label(c('a','b','c','d')[k],x=c(.008,.508,.008,.508)[k],y=c(.992,.992,.492,.492)[k],hjust=0,vjust=1,fontfamily='Arial',fontface='bold',size=12)
for(ext in c('pdf','svg','eps','png')){f<-file.path(here,paste0('Figure_finite_recovery.',ext));if(ext=='pdf')ggsave(f,g,width=7.1,height=6.4,device=cairo_pdf,bg='white')else if(ext=='svg')ggsave(f,g,width=7.1,height=6.4,device=svglite,bg='white')else if(ext=='eps')ggsave(f,g,width=7.1,height=6.4,device=cairo_ps,onefile=FALSE,bg='white')else ggsave(f,g,width=7.1,height=6.4,dpi=300,bg='white')}
